.toggle-switch {
  border-radius: 17px;
  cursor: pointer;
  display: inline-block;
  height: 17px;
  position: relative;
  width: 28px;
}
.toggle-switch input[type=checkbox] {
  display: none;
}
.toggle-switch input[type=checkbox] + .checkbox {
  transition: all 0.3s ease;
  background: #e8e8e8;
  border-radius: 17px;
  border: none;
  cursor: pointer;
  height: 17px;
  margin: 0;
  padding: 0;
  position: relative;
  width: 28px;
  z-index: 0;
}
.toggle-switch input[type=checkbox] + .checkbox:before {
  transform: scale(1);
  transition: all 0.3s ease;
  position: absolute;
  top: 2px;
  right: 0;
  bottom: 0;
  left: 2px;
  background: white;
  border-radius: 17px;
  content: "";
  height: 13px;
  width: 24px;
  z-index: 1;
}
.toggle-switch input[type=checkbox] + .checkbox:after {
  transition: all 0.3s ease;
  height: 13px;
  width: 13px;
  position: absolute;
  top: 2px;
  right: 0;
  bottom: 0;
  left: 2px;
  background: white;
  border-radius: 13px;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.4);
  content: "";
  z-index: 2;
}
.toggle-switch input[type=checkbox]:checked + .checkbox {
  background: #36ac9c;
}
.toggle-switch input[type=checkbox]:checked + .checkbox:before {
  transform: scale(0);
}
.toggle-switch input[type=checkbox]:checked + .checkbox:after {
  left: 13px;
}

