.local-media-placeholder {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  overflow: hidden;
  border: 1px dashed #91aaa5;
  color: #355b55;
  background: #e4efec;
  font: 600 12px/1.4 Arial, Helvetica, sans-serif;
  text-align: center;
  vertical-align: middle;
}

.project-page .masthead .hero-image.local-media-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  border: 1px dashed #91aaa5;
  background: linear-gradient(140deg, #e1efec, #c4ddd8 56%, #b2d1ca) !important;
  color: #345b54;
}

.project-page .masthead .hero-image.local-media-placeholder::before {
  display: grid;
  width: 56px;
  height: 56px;
  place-items: center;
  border-radius: 50%;
  color: #fff;
  background: rgba(26, 86, 78, .78);
  content: "\25B6";
  font: 20px/1 Arial, Helvetica, sans-serif;
}

.project-page .masthead .hero-image.local-media-placeholder::after {
  content: "Hero image / video placeholder";
  font: 600 14px/1.4 Arial, Helvetica, sans-serif;
}

.project-page .masthead .hero-image.local-media-placeholder .play,
.project-page .masthead .hero-image.local-media-placeholder .video-text {
  display: none !important;
}

.local-media-placeholder.medium-avatar {
  display: inline-flex;
  width: 100px;
  height: 100px;
  border-radius: 50%;
  font-size: 8px;
}

.backer-faces .local-media-placeholder {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  font-size: 7px;
}

.preview-thumb.local-media-placeholder,
.results-image.local-media-placeholder {
  display: flex;
  min-height: 120px;
  align-items: center;
  justify-content: center;
  border: 1px dashed #91aaa5;
  background: linear-gradient(140deg, #e1efec, #c4ddd8) !important;
}

.preview-thumb.local-media-placeholder::after,
.results-image.local-media-placeholder::after {
  content: "Project image placeholder";
  font: 600 12px/1.4 Arial, Helvetica, sans-serif;
}

#lightboxOverlay,
#lightbox,
.lb-container,
.hidden-modal-banner {
  display: none !important;
}
